-- Admin, catalog, transaction control and session statements
BEGIN;
BEGIN ISOLATION LEVEL SERIALIZABLE;
BEGIN TRANSACTION READ ONLY;
COMMIT;
ROLLBACK;
SAVEPOINT sp1;
ROLLBACK TO SAVEPOINT sp1;
RELEASE SAVEPOINT sp1;
SET search_path TO public, analytics;
SET LOCAL statement_timeout = '5s';
SET SESSION TIME ZONE 'UTC';
SET lock_timeout = 0;
RESET ALL;
SHOW server_version;
EXPLAIN SELECT * FROM users WHERE id = 1;
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) SELECT * FROM orders WHERE user_id = 5;
EXPLAIN ANALYZE UPDATE t SET x = 1;
GRANT SELECT, INSERT ON users TO app_rw;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO admin_role;
REVOKE UPDATE ON orders FROM readonly;
CREATE ROLE app_user LOGIN PASSWORD 'secret';
SELECT pg_size_pretty(pg_total_relation_size('orders')), pg_relation_size('orders');
SELECT schemaname, relname, n_live_tup, n_dead_tup FROM pg_stat_user_tables ORDER BY n_dead_tup DESC LIMIT 20;
SELECT pid, usename, state, now() - query_start AS runtime, query FROM pg_stat_activity WHERE state <> 'idle' AND pid <> pg_backend_pid() ORDER BY runtime DESC;
SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = 'mydb' AND state = 'idle in transaction';
SELECT c.relname, a.attname, format_type(a.atttypid, a.atttypmod) FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND a.attnum > 0 AND NOT a.attisdropped;
SELECT table_name, column_name, data_type, is_nullable FROM information_schema.columns WHERE table_schema = 'public' ORDER BY table_name, ordinal_position;
SELECT indexrelid::regclass, indisunique FROM pg_index WHERE indrelid = 'orders'::regclass;
SELECT nspname || '.' || relname AS name FROM pg_class JOIN pg_namespace ON pg_namespace.oid = relnamespace WHERE relkind = 'r';
SELECT pg_advisory_lock(12345), pg_try_advisory_xact_lock(1, 2);
SELECT nextval('order_seq'), currval('order_seq'), setval('order_seq', 1000);
SELECT set_config('app.current_user', '42', true);
SELECT pg_notify('channel', 'payload');
LISTEN channel;
NOTIFY channel, 'hello';
ANALYZE users;
LOCK TABLE users IN ACCESS EXCLUSIVE MODE;
PREPARE stmt (int) AS SELECT * FROM users WHERE id = $1;
EXECUTE stmt(5);
DEALLOCATE stmt;
DO $$ BEGIN RAISE NOTICE 'hi'; END $$;
CREATE POLICY tenant_isolation ON orders USING (tenant_id = current_setting('app.tenant')::int);
CREATE OR REPLACE FUNCTION touch() RETURNS trigger AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER trg_touch BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION touch();
CREATE FUNCTION add(a int, b int) RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT a + b $$;
